        frappe.throw("Notification not found", frappe.DoesNotExistError)
    notification = frappe.get_doc("OMC Notification", notification_id)
    if not notification.visible_to_customer:
        frappe.throw("Notification not found", frappe.DoesNotExistError)
    user = _current_user()
